/* Open World Mayhem — personagem Goku (malha + textura + pesos de skin para o esqueleto do jogo).
 This work is based on "Goku low poly" (https://sketchfab.com/3d-models/goku-low-poly-99ac9668648941209fa909d20af55516)
 by minhdoan (https://sketchfab.com/minhdoan) licensed under CC-BY-4.0 (http://creativecommons.org/licenses/by/4.0/).
 Modificado para o jogo: eixos convertidos (frente = +Z, esquerda = +X), escala p/ ~1.73, pesos de skin REFEITOS para o esqueleto de 11 ossos do jogo
 (hip, upper, hm, LA, LE, RA, RE, LL, LK, RL, RK — o mesmo de lowpoly.js, por isso todas as animações continuam compatíveis),
 malha dividida em 6 regiões pintáveis (pele, cabelo, camisa, calça, faixa, sapatos) e textura convertida em mapa de luminância:
 a cor de cada região vem do material (cor escolhida no criador de personagem × K da região), o sombreado/contornos pintados vêm do atlas.
 Este arquivo SUBSTITUI OWM.lp.parts (o esqueleto e as posições dos ossos continuam os de lowpoly.js). Deve ser carregado logo depois de lowpoly.js. */
(()=>{
const LP=OWM.lp;
if(!LP){console.error('[OWM] goku.js: lowpoly.js não carregado');return}
const d=(s,T)=>{const b=atob(s),u=new Uint8Array(b.length);for(let i=0;i<b.length;i++)u[i]=b.charCodeAt(i);return T===Uint8Array?u:new T(u.buffer)};
const mk=o=>{
 const si8=d(o.si,Uint8Array),sw8=d(o.sw,Uint8Array),si=new Uint16Array(si8.length),sw=new Float32Array(sw8.length);
 for(let i=0;i<si.length;i+=4){let s=0;for(let q=0;q<4;q++){si[i+q]=si8[i+q];s+=sw8[i+q]}s=s||1;for(let q=0;q<4;q++)sw[i+q]=sw8[i+q]/s}   // renormaliza os pesos (vieram em 0..255)
 return{pos:d(o.pos,Float32Array),nrm:d(o.nrm,Int8Array),uv:d(o.uv,Float32Array),idx:d(o.idx,Uint16Array),si,sw,tex:o.tex,noSub:true};   // noSub: sem subdivisão nem física de roupa (a malha já é lisa e tem UV)
};
const RAW={"skin":{"pos":"","nrm":"","uv":"","si":"","sw":"","idx":"","tex":"body"},"shirt":{"pos":"","nrm":"","uv":"","si":"","sw":"","idx":"","tex":"body"},"pants":{"pos":"","nrm":"","uv":"","si":"","sw":"","idx":"","tex":"body"},"shoes":{"pos":"","nrm":"","uv":"","si":"","sw":"","idx":"","tex":"body"},"sash":{"pos":"","nrm":"","uv":"","si":"","sw":"","idx":"","tex":"body"},"hair":{"pos":"","nrm":"","uv":"","si":"","sw":"","idx":"","tex":"hair"}};
const parts={};for(const k in RAW)parts[k]=mk(RAW[k]);
LP.partsOld=LP.parts;LP.parts=parts;
LP.model='goku';
LP.slots=['skin','hair','shirt','pants','shoes','sash'];
/* cor "nativa" de cada região (a que reproduz exatamente o desenho original do modelo) e multiplicador K do mapa de luminância */
LP.native={"skin": "#fefcac", "shirt": "#ffa138", "pants": "#ffa138", "shoes": "#0a005a", "sash": "#0a005a", "hair": "#0c0c10"};
LP.K={"skin": 1.3, "shirt": 1.3, "pants": 1.6264, "shoes": 8.0, "sash": 8.0, "hair": 1.0};
/* ajuste (escala + deslocamento) dos cabelos procedurais de hair.js, que foram feitos para a cabeça do modelo antigo */
LP.headFit={"ox": 0, "oy": 1.7, "oz": 0, "cx": 0, "cy": 1.635, "cz": 0.04, "kx": 1.16, "ky": 1.18, "kz": 1.14};
LP.hairName='Goku';
/* texturas (atlas em escala de cinza, sRGB). v já vem invertido (flipY padrão do three) */
const URI={body:'data:image/png;base64,',hair:'data:image/png;base64,'},cache={};
LP.getTexture=key=>{
 if(cache[key])return cache[key];
 const img=new Image(),t=new THREE.Texture(img);
 t.encoding=THREE.sRGBEncoding;t.anisotropy=4;
 img.onload=()=>{t.needsUpdate=true};
 img.src=URI[key];
 return cache[key]=t;
};
})();
